def _loop_module_variable(for_node: ast.For) -> str | None:
    """Return the loop variable that binds to the iterated module (last name for tuple targets)."""
    target = for_node.target
    if isinstance(target, ast.Name):
        return target.id
    if isinstance(target, ast.Tuple):
        names = [element.id for element in target.elts if isinstance(element, ast.Name)]
        if names:
            return names[-1]
    return None


def _collect_trf011_forward_violations(
